fragment:
precision highp float;
varying vec2 vUV;
uniform sampler2D uImage;
uniform float uPhase;
const vec2 px=vec2(1.0/1920.0,1.0/1080.0);
float luminance(vec3 c){return dot(c,vec3(0.2126,0.7152,0.0722));}
float hash21(vec2 p){
  p=fract(p*vec2(123.34,456.21));
  p+=dot(p,p+45.32);
  return fract(p.x*p.y);
}
mat2 rotate2d(float a){
  float s=sin(a),c=cos(a);
  return mat2(c,-s,s,c);
}
float sparkleLayer(vec2 uv,float p,vec2 gridSize,float threshold,float phaseShift){
  vec2 grid=uv*gridSize;
  vec2 id=floor(grid);
  vec2 cell=fract(grid)-0.5;
  float seed=hash21(id+phaseShift);
  vec2 offset=(vec2(hash21(id+vec2(2.7,8.1)),hash21(id+vec2(7.3,1.9)))-0.5)*0.66;
  vec2 d=cell-offset;
  float frequency=2.0+floor(seed*3.0);
  float pulse=pow(0.5+0.5*sin(p*frequency+seed*6.2831853),12.0);
  float selected=step(threshold,seed);
  float core=exp(-dot(d,d)*460.0);
  float halo=exp(-dot(d,d)*70.0)*0.02;
  float cross=(exp(-abs(d.x)*92.0-abs(d.y)*7.0)+exp(-abs(d.y)*92.0-abs(d.x)*7.0))*0.22;
  float diagonal=(exp(-abs(d.x+d.y)*88.0-abs(d.x-d.y)*8.0)+exp(-abs(d.x-d.y)*88.0-abs(d.x+d.y)*8.0))*0.06;
  return selected*pulse*(core+halo+cross+diagonal);
}
void main(){
float p=uPhase;
vec2 uv=(vUV-0.5)/1.04+0.5+vec2(12.0*sin(p),7.0*cos(p))*px;
vec3 guide=texture2D(uImage,uv).rgb;
float gas=smoothstep(0.045,0.33,guide.b-guide.r*0.62);

// The violet star band on the right is pulled into a soft, breathing vortex.
float right=smoothstep(0.48,0.76,vUV.x);
vec2 vortexCenter=vec2(0.79,0.49);
vec2 local=uv-vortexCenter;
local.x*=1.7777778;
float radius=length(local);
float vortexFalloff=right*smoothstep(0.72,0.07,radius);
float twist=(0.060*sin(p)+0.024*sin(2.0*p+radius*18.0))*vortexFalloff;
local=rotate2d(twist)*local;
local.x/=1.7777778;
uv=vortexCenter+local;

// A second wave carries the right-hand star stream along its diagonal ridge.
vec2 ribbonFlow=vec2(
  7.0*sin(p+uv.y*11.0)+3.0*sin(3.0*p-uv.y*17.0),
  9.0*cos(2.0*p+uv.x*8.0)+3.0*sin(p+uv.x*15.0)
)*px;
uv+=ribbonFlow*right*(0.38+0.62*vortexFalloff);

guide=texture2D(uImage,uv).rgb;
gas=smoothstep(0.045,0.33,guide.b-guide.r*0.62);
vec2 flow=vec2(sin(uv.y*14.0+p)+0.38*sin(uv.x*19.0-p*2.0),
cos(uv.x*12.0+p)+0.35*cos(uv.y*18.0+p*2.0));
uv+=flow*px*(2.2+4.3*right)*gas;
vec3 c=texture2D(uImage,uv).rgb;
float center=luminance(c);
float around=(luminance(texture2D(uImage,uv+vec2(2.0,0.0)*px).rgb)
+luminance(texture2D(uImage,uv-vec2(2.0,0.0)*px).rgb)
+luminance(texture2D(uImage,uv+vec2(0.0,2.0)*px).rgb)
+luminance(texture2D(uImage,uv-vec2(0.0,2.0)*px).rgb))*0.25;
float star=smoothstep(0.018,0.13,center-around);
// Animated star pulses begin only on the right side. The source stars on the
// left stay completely static.
float twinkleSide=step(0.52,vUV.x)*smoothstep(0.56,0.72,vUV.x);
float twinkle=sin(p*3.0+uv.x*53.0+uv.y*31.0)*(0.17+0.08*right)
+sin(p*5.0-uv.x*37.0+uv.y*19.0)*(0.07+0.04*right);
float breath=(0.030+0.035*right)*sin(p+uv.x*5.0-uv.y*4.0)*gas;
c*=1.0+twinkle*star*twinkleSide+breath;

// Two deterministic sparkle fields create dense blue-violet bling on the right.
// Their coordinates share the vortex, so the sparkles travel with the star band.
vec2 sparkleUV=uv+vec2(0.004*sin(2.0*p+uv.y*9.0),0.006*cos(p+uv.x*7.0))*right;
float bling=sparkleLayer(sparkleUV,p,vec2(58.0,33.0),0.97,1.7);
bling+=0.18*sparkleLayer(sparkleUV+vec2(0.006,-0.004),p,vec2(96.0,54.0),0.99,9.2);
float blingMask=step(0.52,vUV.x)*smoothstep(0.56,0.94,vUV.x)*(0.36+0.64*smoothstep(0.02,0.34,guide.b+guide.r*0.45-guide.g*0.38));
vec3 blingColor=mix(vec3(0.42,0.80,1.0),vec3(0.76,0.48,1.0),smoothstep(0.62,1.0,vUV.x));
c+=blingColor*bling*blingMask*0.10;
gl_FragColor=vec4(c,1.0);
}
